public final class Config {
    private final String name;
    private final List<Integer> ports;

    private Config(String name, List<Integer> ports) {
        this.name = name;
        this.ports = Collections.unmodifiableList(new ArrayList<>(ports));  // private copy
    }

    public static Config of(String name, List<Integer> ports) { return new Config(name, ports); }

    public List<Integer> ports() { return ports; }                          // no alias to caller state

    public Config withPort(int port) {
        List<Integer> next = new ArrayList<>(ports);
        next.add(port);
        return new Config(name, next);
    }
}

import io.vavr.collection.List;

final class Router {
    private final List<Route> routes;                 // persistent, shared tail

    Router withRoute(Route route) {
        return new Router(routes.prepend(route));     // O(1); the old version is intact
    }
}

